/**
 * Demo accounts, one per fictional buyer, created by supabase/seed.sql
 * (generated by supabase/generate_seed_sql.py — keep the two in sync).
 *
 * The password is a LOCAL TEST VALUE for fictional users, not a secret: it's only useful
 * against a database seeded with these demo accounts. Real sign-in replaces this before any
 * real buyer uses SupplyPilot.
 */
import type { SupabaseClient } from "@supabase/supabase-js";

export const DEMO_ORG_COOKIE = "sp_demo_org";
export const DEFAULT_DEMO_ORG = "org_sundaycrumb";
export const DEMO_PASSWORD = "supplypilot-demo-only";

const ORG_ID = /^org_[a-z0-9_]+$/;

export function isOrgId(id: string): boolean {
  return ORG_ID.test(id);
}

export function demoEmail(orgId: string): string {
  if (!isOrgId(orgId)) throw new Error(`Not an org id: ${orgId}`);
  return `demo.${orgId.slice("org_".length)}@supplypilot.test`;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- works with any typed client
export async function signInAsDemoBuyer(client: SupabaseClient<any, any, any>, orgId: string) {
  const { error } = await client.auth.signInWithPassword({
    email: demoEmail(orgId),
    password: DEMO_PASSWORD,
  });
  return error ? { ok: false as const, error: error.message } : { ok: true as const };
}
